<?php
use App\Core\{DB,Security};
use App\Models\{Workflow,Project,Ticket,TicketFollow,TicketNotification};
use App\Services\{Query,Conversation};
$wp=Project::save(['name'=>'Circuit personnalisé','key'=>'WF'.strtoupper(bin2hex(random_bytes(3)))]);
$wother=Project::save(['name'=>'Circuit indépendant','key'=>'WO'.strtoupper(bin2hex(random_bytes(3)))]);
$wf=Workflow::get($wp);
check($wf['version']===0 && !$wf['restricted'],'circuit initial conserve les passages libres');
$wf=Workflow::save($wp,['version'=>0,'action'=>'add_item','kind'=>'status','label'=>'Attente du client','category'=>'progress','icon'=>'clock','color'=>'#0891b2','position'=>15]);
$waiting=array_values(array_diff(array_keys($wf['items']['status']),array_keys(Ticket::STATUSES)))[0];
$wf=Workflow::save($wp,['version'=>$wf['version'],'action'=>'add_item','kind'=>'status','label'=>'Livré','category'=>'done','icon'=>'check','color'=>'#15803d','position'=>35]);
$delivered=array_values(array_diff(array_keys($wf['items']['status']),[...array_keys(Ticket::STATUSES),$waiting]))[0];
$wf=Workflow::save($wp,['version'=>$wf['version'],'action'=>'add_item','kind'=>'type','label'=>'Incident métier','category'=>'bug','icon'=>'bug','color'=>'#dc2626','position'=>5]);
$incident=array_values(array_diff(array_keys($wf['items']['type']),array_keys(Ticket::TYPES)))[0];
check(!isset(Workflow::labels('status',$wother)[$waiting]) && isset(Workflow::labels('status')[$waiting]),'statut isolé par projet et découvrable dans les filtres globaux');
rejects(fn()=>Workflow::save($wp,['version'=>0,'action'=>'transitions']),'version de circuit obsolète refusée');
$wu=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'member',UTC_TIMESTAMP())",['wf.'.bin2hex(random_bytes(5)).'@example.com','Personne mentionnée',Security::password('Tests-Workflow-2026!')]);
$wv=DB::insert("INSERT INTO users(email,name,password_hash,role,verified_at) VALUES(?,?,?,'viewer',UTC_TIMESTAMP())",['wv.'.bin2hex(random_bytes(5)).'@example.com','Personne qui suit',Security::password('Tests-Workflow-2026!')]);
$wt=Ticket::create($wp,['title'=>'Validation de circuit','type'=>$incident,'assignee_id'=>$wu],$uid);
check(Ticket::find($wt)['type_label']==='Incident métier','type personnalisé hydraté depuis son projet');
$wf=Workflow::save($wp,['version'=>$wf['version'],'action'=>'transitions','restricted'=>1,'transitions'=>['todo'=>[$waiting],$waiting=>[$delivered]]]);
rejects(fn()=>Ticket::patch($wt,['status'=>$delivered],$uid,Ticket::find($wt)['version']),'passage interdit refusé dans le modèle métier');
Ticket::patch($wt,['status'=>$waiting],$uid,Ticket::find($wt)['version']);
check(Query::count($wp,['jql'=>'status = "Attente du client"'])===1,'recherche avancée interprète le libellé du projet');
Ticket::setPaused($wt,true,$uid,Ticket::find($wt)['version']);
rejects(fn()=>Ticket::patch($wt,['status'=>'done'],$uid,Ticket::find($wt)['version']),'pause ne contourne pas les transitions du statut précédent');
rejects(fn()=>Workflow::save($wp,['version'=>Workflow::get($wp)['version'],'action'=>'save_item','kind'=>'status','code'=>$waiting,'enabled'=>false]),'état mémorisé par une pause protégé contre désactivation');
Ticket::setPaused($wt,false,$uid,Ticket::find($wt)['version']);
check(Ticket::find($wt)['status']===$waiting,'pause et reprise préservent le statut personnalisé');
Ticket::patch($wt,['status'=>$delivered],$uid,Ticket::find($wt)['version']);
check(Ticket::find($wt)['completed_at']!==null && Query::count($wp,['hide_done'=>1])===0,'catégorie terminé pilote résolution et filtrage');
check((int)Query::teamWorkload($wp,[])[0]['done']===1,'rapport de charge reconnaît les statuts terminés personnalisés');
rejects(fn()=>Workflow::save($wp,['version'=>$wf['version'],'action'=>'save_item','kind'=>'status','code'=>$delivered,'label'=>'Livré','category'=>'done','icon'=>'check','color'=>'#15803d','enabled'=>0]),'statut utilisé protégé contre désactivation');
rejects(fn()=>Workflow::save($wp,['version'=>$wf['version'],'action'=>'save_item','kind'=>'status','code'=>$delivered,'label'=>'Livré','category'=>'progress','icon'=>'check','color'=>'#15803d','enabled'=>1]),'catégorie utilisée immuable');
rejects(fn()=>Ticket::create($wother,['title'=>'État étranger','status'=>$waiting],$uid),'ticket refuse un statut étranger');
$beforeFollow=Ticket::find($wt)['version'];TicketFollow::set($wt,$wv,true);TicketFollow::set($wt,$wv,true);
check(TicketFollow::get($wt,$wv)['count']===1 && Ticket::find($wt)['version']===$beforeFollow,'suivi personnel idempotent sans modifier la version du ticket');
$unread=TicketNotification::unread($wv);
Ticket::patch($wt,['title'=>'Nouvelle précision'],$uid,Ticket::find($wt)['version']);
check(TicketNotification::unread($wv)===$unread+1,'suivi produit une notification interne même sans e-mails activés');
$cid=Ticket::comment($wt,'<p>Bonjour <span data-mention-id="'.$wv.'">Nom falsifié</span> et <span data-mention-id="'.$wv.'">Autre nom</span></p>',$uid,'html');
$stored=DB::one('SELECT * FROM comments WHERE id=?',[$cid]);
check(str_contains($stored['body'],'@Personne qui suit') && !str_contains($stored['body'],'falsifié'),'identité des mentions normalisée côté serveur');
$notice=DB::one('SELECT * FROM ticket_notifications WHERE user_id=? AND comment_id=?',[$wv,$cid]);
check($notice && $notice['mentioned'] && (int)DB::one('SELECT COUNT(*) n FROM ticket_notifications WHERE user_id=? AND comment_id=?',[$wv,$cid])['n']===1,'mention et suivi ne créent qu’une notification par destinataire');
check(!DB::one('SELECT id FROM ticket_notifications WHERE user_id=? AND comment_id=?',[$uid,$cid]),'auteur non notifié de sa propre action');
$read=TicketNotification::mark((int)$notice['id'],$wv,true);
check($read['read'] && DB::one('SELECT read_at FROM ticket_notifications WHERE id=?',[$notice['id']])['read_at']!==null,'lecture personnelle persistée');
rejects(fn()=>TicketNotification::mark((int)$notice['id'],$wu,true),'notification d’un autre utilisateur inaccessible');
TicketNotification::mark((int)$notice['id'],$wv,false);
check(DB::one('SELECT read_at FROM ticket_notifications WHERE id=?',[$notice['id']])['read_at']===null,'notification marquée non lue');
TicketFollow::set($wt,$wv,false);$unread=TicketNotification::unread($wv);Ticket::comment($wt,'Pas de mention cette fois',$uid);
check(TicketNotification::unread($wv)===$unread,'désabonnement arrête les prochaines notifications de suivi');
$textComment=Ticket::comment($wt,'Question pour @[user:'.$wv.']',$uid);
check(DB::one('SELECT id FROM ticket_notifications WHERE user_id=? AND comment_id=? AND mentioned=1',[$wv,$textComment])!==null,'jeton de mention texte pris en charge pour API et MCP');
DB::run('UPDATE users SET active=0 WHERE id=?',[$wv]);
check(str_contains(Conversation::render($stored),'@Personne qui suit'),'désactivation ultérieure conserve le commentaire et sa mention');
rejects(fn()=>Ticket::comment($wt,'@[user:'.$wv.']',$uid),'nouvelle mention d’un compte inactif refusée');
DB::run('UPDATE users SET active=1 WHERE id=?',[$wv]);
$unread=TicketNotification::unread($wv);DB::run('SAVEPOINT inbox_rollback');Ticket::comment($wt,'@[user:'.$wv.']',$uid);DB::run('ROLLBACK TO SAVEPOINT inbox_rollback');
check(TicketNotification::unread($wv)===$unread,'annulation du commentaire annule aussi sa notification');
TicketNotification::readAll($wv);check(TicketNotification::unread($wv)===0 && TicketNotification::unread($wu)>0,'tout marquer lu reste limité au compte connecté');
\App\Models\ProjectEmail::save($wp,['version'=>0,'enabled'=>1,'rules'=>['commented'=>['followers','mentioned']]]);
TicketFollow::set($wt,$wv,true);$mailComment=Ticket::comment($wt,'Texte privé pour @[user:'.$wv.']',$uid);
$mentionMail=DB::all('SELECT body FROM notification_outbox WHERE ticket_id=? AND recipient_id=?',[$wt,$wv]);
check(count($mentionMail)===1 && !str_contains($mentionMail[0]['body'],'Texte privé'),'e-mail de mention et de suivi dédupliqué sans recopier le commentaire');
$previousWaiting=Workflow::item('status',$wp,$waiting);
$wf=Workflow::save($wp,['version'=>Workflow::get($wp)['version'],'action'=>'save_item','kind'=>'status','code'=>$waiting,'label'=>'Attente renommée']);
check($wf['items']['status'][$waiting]['enabled'] && $wf['items']['status'][$waiting]['position']===$previousWaiting['position'] && $wf['items']['status'][$waiting]['color']===$previousWaiting['color'],'modification partielle du circuit conserve disponibilité ordre et couleur');
Workflow::reset();
